rows("world-sci", "WORLD", "Astronomie", [
    (1, "Quelle est la planète la plus éloignée du Soleil depuis que Pluton a été reclassée ?", "Neptune", ["Uranus", "Saturne", "Pluton", "Jupiter"], "Neptune est la huitième et dernière planète du système solaire."),
    (2, "Quelle planète se trouve entre la Terre et Jupiter ?", "Mars", ["Vénus", "Saturne", "Mercure", "Uranus"], "L'ordre est : Mercure, Vénus, Terre, Mars, Jupiter, Saturne, Uranus, Neptune."),
    (3, "Quelle planète tourne autour du Soleil presque « couchée » sur le côté ?", "Uranus", ["Mars", "Mercure", "Jupiter", "Vénus"], "L'axe d'Uranus est incliné d'environ 98° : la planète roule pour ainsi dire sur son orbite."),
    (2, "Comment s'appelle la galaxie dans laquelle se trouve notre système solaire ?", "La Voie lactée", ["Andromède", "Le Grand Nuage", "La Galaxie du Tourbillon", "Orion"], "Vue de la Terre, elle forme une bande laiteuse de milliards d'étoiles."),
    (4, "Quelle grande galaxie spirale, visible à l'œil nu depuis un ciel noir, est la voisine de la Voie lactée ?", "Andromède", ["Orion", "Le Triangle austral", "La Grande Ourse", "Cassiopée"], "La galaxie d'Andromède (M31) est à environ 2,5 millions d'années-lumière."),
    (3, "Quelle étoile, après le Soleil, est la plus proche de la Terre ?", "Proxima du Centaure", ["Sirius", "Véga", "Rigel", "L'étoile Polaire"], "Proxima est à un peu plus de quatre années-lumière."),
    (2, "L'année-lumière est une unité de mesure de quoi ?", "Une distance", ["Un temps", "Une vitesse", "Une luminosité", "Une masse"], "C'est la distance que parcourt la lumière en un an, soit environ 9 460 milliards de kilomètres."),
    (3, "Combien de temps la lumière du Soleil met-elle environ à atteindre la Terre ?", "Environ 8 minutes", ["Environ 8 secondes", "Environ 1 heure", "Environ 1 jour", "Une fraction de seconde"], "Le Soleil est à environ 150 millions de kilomètres : on le voit tel qu'il était il y a 8 minutes."),
    (4, "Quelles sont les deux petites lunes de Mars ?", "Phobos et Déimos", ["Io et Europe", "Titan et Encelade", "Triton et Charon", "Ariel et Obéron"], "Phobos (« peur ») et Déimos (« terreur ») furent découvertes en 1877 par Asaph Hall."),
    (4, "Quelle est la plus grande lune du système solaire ?", "Ganymède", ["Titan", "La Lune", "Callisto", "Triton"], "Ganymède, lune de Jupiter, dépasse même la planète Mercure en diamètre."),
    (4, "Laquelle de ces lunes n'est PAS l'une des quatre « lunes galiléennes » de Jupiter ?", "Titan", ["Io", "Europe", "Callisto", "Ganymède"], "Titan tourne autour de Saturne. Galilée a découvert Io, Europe, Ganymède et Callisto en 1610."),
    (3, "Quelle lune de Saturne possède une épaisse atmosphère orangée ?", "Titan", ["Mimas", "Phobos", "Triton", "Encelade"], "Titan est la seule lune du système solaire dotée d'une atmosphère aussi dense."),
    (2, "Que sont les « étoiles filantes » que l'on voit traverser le ciel la nuit ?", "De petits grains de roche qui brûlent dans l'atmosphère", ["Des étoiles qui tombent sur Terre", "Des satellites en panne", "Des éclairs très lointains", "Des planètes qui explosent"], "Ces météoroïdes s'enflamment par frottement vers 100 km d'altitude."),
    (3, "À peu près tous les combien d'années la comète de Halley repasse-t-elle près de la Terre ?", "Environ tous les 76 ans", ["Environ tous les 7 ans", "Environ tous les 150 ans", "Environ tous les 20 ans", "Environ tous les 300 ans"], "Elle est passée en 1986 et sera de retour en 2061."),
    (2, "Pendant une éclipse totale de Soleil, quel astre passe entre la Terre et le Soleil ?", "La Lune", ["Mars", "Vénus", "Une comète", "Mercure"], "La Lune masque alors le disque solaire pour quelques minutes au plus."),
    (3, "Lors d'une éclipse de Lune, quel astre se place entre le Soleil et la Lune ?", "La Terre", ["Mars", "Vénus", "Jupiter", "Personne : la Lune s'éteint seule"], "La Lune traverse l'ombre de la Terre et prend souvent une teinte rougeâtre."),
    (1, "Quel mouvement de la Terre provoque l'alternance du jour et de la nuit ?", "Sa rotation sur elle-même", ["Son tour autour du Soleil", "Le déplacement de la Lune", "L'éclipse du Soleil", "L'inclinaison des nuages"], "La Terre tourne sur son axe en environ 24 heures."),
    (2, "Quelle est la cause principale des saisons sur Terre ?", "L'inclinaison de l'axe de rotation de la Terre", ["La distance entre la Terre et le Soleil", "Les phases de la Lune", "La vitesse du vent solaire", "Les taches sur le Soleil"], "L'axe est incliné d'environ 23,4° : selon la saison, un hémisphère reçoit plus directement la lumière."),
    (3, "Que dit-on de la durée du jour et de la nuit aux équinoxes ?", "Elles sont à peu près égales", ["Le jour dure 24 heures", "La nuit dure 24 heures", "Le jour est deux fois plus long", "La nuit est deux fois plus longue"], "« Équinoxe » vient du latin pour « nuit égale »."),
    (1, "Dans quelle direction le Soleil se lève-t-il ?", "À l'est", ["À l'ouest", "Au nord", "Au sud", "Au sud-est"], "La Terre tourne vers l'est, ce qui fait paraître le Soleil se lever à l'est."),
    (3, "Quelle réaction nucléaire produit l'énergie du Soleil ?", "La fusion de l'hydrogène en hélium", ["La combustion du charbon", "La fission de l'uranium", "Une réaction chimique avec l'oxygène", "La désintégration du radium"], "Au cœur du Soleil, les noyaux d'hydrogène fusionnent en noyaux d'hélium."),
    (3, "En quelle année l'Union astronomique internationale a-t-elle reclassé Pluton parmi les planètes naines ?", "2006", ["1996", "2001", "2012", "1930"], "Pluton, découverte en 1930, ne remplit pas le critère de « nettoyage » de son orbite."),
    (3, "Entre quelles planètes se situe la principale ceinture d'astéroïdes ?", "Mars et Jupiter", ["Terre et Mars", "Vénus et la Terre", "Saturne et Uranus", "Uranus et Neptune"], "Cérès, planète naine, en est le plus gros objet."),
    (4, "Comment s'appelle le plus haut volcan connu du système solaire, situé sur Mars ?", "Olympus Mons", ["Mauna Kea", "Kilimandjaro", "Etna Mons", "Valles Marineris"], "Olympus Mons atteint environ deux fois et demie la hauteur de l'Everest."),
    (3, "Qu'est-ce que la Grande Tache rouge de Jupiter ?", "Une gigantesque tempête", ["Un volcan", "Un cratère d'impact", "Un océan de lave", "Un anneau de glace"], "Cette tempête tourbillonne depuis au moins plusieurs siècles."),
    (5, "Pourquoi un jour de Vénus est-il plus long que son année ?", "Elle tourne sur elle-même plus lentement qu'elle ne fait le tour du Soleil", ["Elle n'a pas d'axe de rotation", "Elle est plus proche de la Lune", "Son orbite est circulaire", "Elle tourne plus vite que la Terre"], "Vénus effectue un tour sur elle-même en environ 243 jours terrestres, et le tour du Soleil en environ 225."),
    (4, "Pourquoi voit-on toujours la même face de la Lune depuis la Terre ?", "Parce qu'elle tourne sur elle-même en autant de temps qu'elle fait le tour de la Terre", ["Parce qu'elle ne tourne pas", "Parce que l'autre face est toujours dans l'ombre", "Parce que la Lune est plate", "Parce que la Terre la maintient immobile"], "Cette rotation synchrone est due aux forces de marée."),
    (2, "Comment appelle-t-on la phase où la Lune est invisible dans le ciel nocturne ?", "La nouvelle lune", ["La pleine lune", "Le premier quartier", "Le dernier croissant", "L'éclipse annulaire"], "À la nouvelle lune, la face éclairée de la Lune est tournée vers le Soleil, pas vers nous."),
    (3, "Quel astre est principalement responsable des marées océaniques ?", "La Lune", ["Mars", "Le Soleil seul", "Jupiter", "Les vents"], "La Lune attire l'eau des océans ; le Soleil joue un rôle secondaire."),
    (4, "En quelle année les sondes Voyager 1 et Voyager 2 ont-elles été lancées ?", "1977", ["1969", "1985", "1961", "1990"], "Ces deux sondes de la NASA ont survolé les planètes géantes."),
    (4, "En quelle année le télescope spatial Hubble a-t-il été mis en orbite ?", "1990", ["1969", "1981", "1998", "2004"], "Hubble a été déployé par la navette Discovery en avril 1990."),
    (4, "Quel était le nom du module lunaire d'Apollo 11, qui s'est posé sur la Lune en juillet 1969 ?", "Eagle", ["Columbia", "Odyssey", "Challenger", "Intrepid"], "« The Eagle has landed » : Columbia était le module de commande, resté en orbite."),
    (4, "Quel astronaute d'Apollo 11 est resté en orbite lunaire pendant que ses deux collègues descendaient sur la Lune ?", "Michael Collins", ["Buzz Aldrin", "Neil Armstrong", "Alan Shepard", "Jim Lovell"], "Collins pilotait le module de commande Columbia."),
    (3, "Quel animal fut le premier être vivant mis en orbite autour de la Terre, en 1957 ?", "Laïka, une chienne", ["Un singe", "Un chat", "Une souris", "Un lapin"], "Laïka voyageait à bord de Spoutnik 2."),
    (3, "Qui fut la première femme dans l'espace, en 1963 ?", "Valentina Terechkova", ["Sally Ride", "Svetlana Savitskaïa", "Mae Jemison", "Christa McAuliffe"], "Cette cosmonaute soviétique a effectué 48 orbites à bord de Vostok 6."),
    (5, "Quel astronome français a calculé la position de la planète Neptune avant son observation, en 1846 ?", "Urbain Le Verrier", ["Camille Flammarion", "Pierre-Simon de Laplace", "François Arago", "Jules Janssen"], "L'astronome Johann Galle l'a trouvée à Berlin, là où Le Verrier l'avait prévue."),
    (5, "Quel astronome a découvert la planète Uranus en 1781 ?", "William Herschel", ["Galilée", "Edmond Halley", "Giovanni Cassini", "Tycho Brahe"], "Herschel crut d'abord à une comète."),
    (4, "Quel savant a publié en 1543 un ouvrage plaçant le Soleil au centre du monde connu ?", "Nicolas Copernic", ["Ptolémée", "Galilée", "Johannes Kepler", "Isaac Newton"], "Son traité « Des révolutions des sphères célestes » lance l'héliocentrisme."),
    (4, "Quelle forme ont les orbites des planètes selon Johannes Kepler ?", "Des ellipses", ["Des cercles parfaits", "Des spirales", "Des carrés arrondis", "Des lignes droites"], "Kepler formule ces lois au début du XVIIe siècle."),
    (3, "Qu'a observé Galilée avec sa lunette vers 1609-1610 ?", "Les cratères de la Lune et les lunes de Jupiter", ["Les anneaux d'Uranus", "Des canaux sur Mars", "La planète Neptune", "Des volcans sur Vénus"], "Ses observations apportent des arguments à l'héliocentrisme."),
    (5, "Quel prêtre et astronome belge a proposé l'idée d'un « atome primitif » à l'origine de l'Univers ?", "Georges Lemaître", ["Edwin Hubble", "Fred Hoyle", "Paul Dirac", "Hans Bethe"], "Son hypothèse est à l'origine de la théorie du Big Bang."),
    (5, "Quel est le nom du premier module de la Station spatiale internationale, lancé en 1998 ?", "Zarya", ["Columbus", "Harmony", "Destiny", "Zvezda"], "Le module russe Zarya (« Aurore ») est lancé en novembre 1998."),
    (5, "Quel pays a envoyé son premier astronaute dans l'espace en 2003, à bord de Shenzhou 5 ?", "La Chine", ["L'Inde", "Le Japon", "Le Brésil", "La Corée du Sud"], "Yang Liwei devient le premier Chinois dans l'espace."),
    (4, "En quelle année la première fusée Ariane (Ariane 1) a-t-elle décollé de Kourou ?", "1979", ["1969", "1986", "1992", "1973"], "Le premier tir a eu lieu le 24 décembre 1979."),
    (3, "Dans quel territoire d'Amérique du Sud se trouve le port spatial européen ?", "En Guyane (Kourou)", ["Au Brésil (Natal)", "En Argentine (Ushuaïa)", "Au Chili (Valparaíso)", "Au Venezuela (Caracas)"], "Kourou est proche de l'équateur, ce qui aide les fusées à gagner de la vitesse."),
    (5, "En quelle année la première navette spatiale américaine, Columbia, s'est-elle envolée ?", "1981", ["1969", "1975", "1986", "1990"], "Columbia décolle en avril 1981 pour sa première mission."),
    (5, "Quel engin soviétique fut le premier objet fabriqué par l'homme à atteindre la surface de la Lune, en 1959 ?", "Luna 2", ["Spoutnik 3", "Vostok 1", "Venera 1", "Zond 5"], "La sonde Luna 2 s'écrase volontairement sur la Lune en septembre 1959."),
])

# ------------------------------------------------------------------------------------------------ Terre
rows("world-sci", "WORLD", "Terre et géologie", [
    (2, "Comment s'appelle la couche de la Terre située juste sous la croûte ?", "Le manteau", ["Le noyau", "L'hydrosphère", "L'atmosphère", "Le magma central"], "La Terre comprend la croûte, le manteau, puis le noyau."),
    (4, "De quoi est composé le noyau interne de la Terre ?", "De métal solide, surtout du fer et du nickel", ["De roche fondue", "D'eau gelée", "De gaz comprimé", "De sable chaud"], "Le noyau externe est liquide, mais le noyau interne reste solide à cause de la pression."),
    (2, "Quel instrument sert à enregistrer les tremblements de terre ?", "Un sismographe", ["Un baromètre", "Un thermomètre", "Un anémomètre", "Un pluviomètre"], "Il enregistre les vibrations du sol."),
    (3, "Comment s'appelle le supercontinent qui rassemblait toutes les terres émergées il y a environ 250 millions d'années ?", "La Pangée", ["Le Gondwana seul", "L'Atlantide", "La Lémurie", "Mu"], "Il s'est ensuite fragmenté sous l'effet de la tectonique des plaques."),
    (4, "Quel scientifique a proposé en 1912 la théorie de la dérive des continents ?", "Alfred Wegener", ["Charles Darwin", "Charles Richter", "James Hutton", "Ernest Rutherford"], "Il remarquait que les côtes de l'Afrique et de l'Amérique du Sud s'emboîtent."),
    (3, "Comment nomme-t-on la zone de forte activité sismique et volcanique qui borde l'océan Pacifique ?", "La ceinture de feu", ["Le cercle de braise", "La faille du Pacifique", "L'arc de lave", "L'anneau de Magellan"], "Elle concentre une grande part des séismes et volcans du globe."),
    (2, "Comment appelle-t-on la roche en fusion qui sort d'un volcan en éruption ?", "La lave", ["Le basalte froid", "Le granit", "La pierre ponce", "Le tuf"], "Sous terre, la même matière s'appelle magma."),
    (2, "Dans quelle chaîne de montagnes se trouve le mont Everest ?", "L'Himalaya", ["Les Andes", "Les Alpes", "Les Rocheuses", "L'Atlas"], "L'Everest est à la frontière du Népal et de la Chine (Tibet)."),
    (1, "Quel est le plus grand océan du monde ?", "L'océan Pacifique", ["L'océan Atlantique", "L'océan Indien", "L'océan Arctique", "L'océan Austral"], "Il couvre près d'un tiers de la surface de la Terre."),
    (1, "Quel est le plus grand désert chaud du monde ?", "Le Sahara", ["Le Kalahari", "Le Gobi", "Le désert d'Arabie", "Le désert d'Atacama"], "Le Sahara s'étend sur une grande partie de l'Afrique du Nord."),
    (2, "Quelle proportion de la surface de la Terre est couverte d'eau ?", "Environ 70 %", ["Environ 30 %", "Environ 50 %", "Environ 90 %", "Environ 10 %"], "La Terre est surnommée la « planète bleue »."),
    (4, "Dans quelle couche de l'atmosphère se produisent la plupart des phénomènes météorologiques ?", "La troposphère", ["La stratosphère", "La mésosphère", "L'exosphère", "L'ionosphère"], "Elle va du sol jusqu'à une dizaine de kilomètres d'altitude en moyenne."),
    (4, "Dans quelle couche de l'atmosphère se trouve la couche d'ozone ?", "La stratosphère", ["La troposphère", "L'exosphère", "La thermosphère", "La mésosphère"], "L'ozone y absorbe une grande partie des rayons ultraviolets."),
    (3, "Quel gaz est le plus abondant dans l'air que nous respirons ?", "L'azote", ["L'oxygène", "Le dioxyde de carbone", "L'argon", "L'hydrogène"], "L'air contient environ 78 % d'azote et 21 % d'oxygène."),
    (3, "Quel parallèle de latitude passe au nord de l'équateur à environ 23° et porte le nom du Cancer ?", "Le tropique du Cancer", ["Le tropique du Capricorne", "Le cercle polaire arctique", "Le méridien de Greenwich", "Le parallèle d'or"], "Le Soleil est à la verticale du tropique du Cancer au solstice de juin."),
    (4, "Quelle est la roche magmatique (issue du refroidissement du magma) parmi ces roches ?", "Le granit", ["Le calcaire", "Le marbre", "Le grès", "L'ardoise"], "Le granit se forme en profondeur, très lentement, ce qui donne de gros cristaux."),
    (5, "À quelle famille de roches appartient le marbre ?", "Métamorphique, issue du calcaire transformé par la chaleur et la pression", ["Magmatique, issue d'un volcan", "Sédimentaire, formée de coquillages", "Organique, formée par des plantes", "Extraterrestre, tombée du ciel"], "Le calcaire se transforme en marbre en profondeur."),
    (4, "Dans quel type de roche trouve-t-on le plus souvent des fossiles ?", "Les roches sédimentaires", ["Le granit", "Le basalte", "La lave", "L'obsidienne"], "Les sédiments enfouissent peu à peu les restes d'êtres vivants."),
    (3, "De quelle matière le diamant est-il uniquement constitué ?", "De carbone", ["De silice", "De quartz", "De calcium", "De verre"], "Le diamant est du carbone cristallisé sous très haute pression ; le graphite en est une autre forme."),
    (4, "Sur l'échelle de Mohs, quel minéral est le plus dur, avec la note 10 ?", "Le diamant", ["Le quartz", "Le corindon", "Le talc", "La topaze"], "Le talc est à 1, le diamant à 10 : il raye tous les autres."),
    (3, "Qu'est-ce qu'un tsunami ?", "Une série de grosses vagues, souvent causée par un séisme sous la mer", ["Un cyclone très violent", "Une marée très haute", "Un fleuve qui déborde", "Un vent de sable"], "Le mot vient du japonais et signifie « vague de port »."),
    (3, "Quelle éruption a enseveli les villes de Pompéi et Herculanum en l'an 79 ?", "L'éruption du Vésuve", ["L'éruption de l'Etna", "L'éruption du Krakatoa", "L'éruption du Stromboli", "L'éruption du Mont Pelé"], "Pompéi est restée conservée sous les cendres jusqu'aux fouilles modernes."),
    (5, "Quelle échelle permet de classer la force du vent de 0 à 12 ?", "L'échelle de Beaufort", ["L'échelle de Richter", "L'échelle de Mercalli", "L'échelle de Kelvin", "L'échelle de Mohs"], "Elle a été conçue au début du XIXe siècle par l'amiral Francis Beaufort."),
    (2, "Quel instrument mesure la vitesse du vent ?", "Un anémomètre", ["Un baromètre", "Un hygromètre", "Un pluviomètre", "Un sismographe"], "Le baromètre mesure la pression et l'hygromètre l'humidité."),
    (4, "Que mesure un hygromètre ?", "L'humidité de l'air", ["La pression de l'air", "La vitesse du vent", "La température", "La quantité de pluie"], "Le mot vient du grec « hygros », humide."),
    (4, "Où se trouve la plus grande partie de l'eau douce de la planète ?", "Dans les glaciers et les calottes glaciaires", ["Dans les lacs", "Dans les rivières", "Dans l'atmosphère", "Dans les nuages"], "Les glaces polaires et les glaciers stockent environ les deux tiers de l'eau douce."),
    (5, "Quelle est, à l'échelle du globe, la principale cause des tremblements de terre ?", "Le glissement brutal des plaques tectoniques le long des failles", ["L'attraction de la Lune", "Les vents d'altitude", "Les orages", "L'extraction du pétrole"], "L'énergie accumulée aux frontières des plaques se libère d'un coup."),
    (3, "Que pointe l'aiguille d'une boussole ?", "Le nord magnétique", ["L'étoile du Berger", "Le Soleil levant", "Le centre de la Lune", "L'est géographique"], "Elle s'oriente selon le champ magnétique terrestre."),
    (5, "Qu'est-ce qui produit les aurores polaires ?", "Des particules du vent solaire guidées par le champ magnétique terrestre", ["Le reflet de la glace sur la Lune", "Des feux de forêt lointains", "L'ozone qui s'enflamme", "Les nuages d'orage"], "Ces particules excitent les gaz de la haute atmosphère, qui se mettent à luire."),
])

