rows("world-sci", "WORLD", "Corps humain", [
    (1, "Combien de sens traditionnels l'être humain possède-t-il ?", "Cinq", ["Trois", "Quatre", "Sept", "Dix"], "Vue, ouïe, odorat, goût et toucher."),
    (2, "Quelles cellules du sang transportent l'oxygène ?", "Les globules rouges", ["Les globules blancs", "Les plaquettes", "Le plasma", "Les anticorps"], "Elles contiennent l'hémoglobine, qui fixe l'oxygène."),
    (2, "Quel est le rôle principal des globules blancs ?", "Défendre le corps contre les microbes", ["Transporter l'oxygène", "Faire coaguler le sang", "Digérer les aliments", "Produire de la bile"], "Ils font partie du système immunitaire."),
    (3, "Quel est le rôle des plaquettes sanguines ?", "Aider le sang à coaguler", ["Transporter l'oxygène", "Combattre les virus", "Produire l'insuline", "Colorer la peau"], "Elles forment un bouchon qui arrête le saignement."),
    (3, "Quel pigment rend le sang rouge ?", "L'hémoglobine", ["La chlorophylle", "La mélanine", "La kératine", "Le carotène"], "Il contient du fer, qui se lie à l'oxygène."),
    (4, "Quel groupe sanguin est appelé « donneur universel » pour les globules rouges ?", "O négatif", ["AB positif", "A positif", "B négatif", "AB négatif"], "Les globules rouges O négatif ne portent ni antigène A, ni B, ni Rhésus."),
    (5, "Quel médecin autrichien a découvert les groupes sanguins A, B et O vers 1900-1901 ?", "Karl Landsteiner", ["Louis Pasteur", "Robert Koch", "Ignace Semmelweis", "Alexandre Yersin"], "Il a reçu le prix Nobel de médecine en 1930."),
    (3, "Dans quelle partie de l'œil se forme l'image qui est envoyée au cerveau ?", "La rétine", ["La pupille", "La cornée", "L'iris", "Le cristallin"], "La rétine contient les cellules sensibles à la lumière."),
    (3, "Quel élément de l'œil agit comme une lentille qui fait la mise au point ?", "Le cristallin", ["La rétine", "L'iris", "La sclérotique", "Le nerf optique"], "Il change de forme pour voir net de près ou de loin."),
    (2, "Quelle membrane de l'oreille vibre quand elle reçoit un son ?", "Le tympan", ["La rétine", "La cornée", "La cochlée", "Le pavillon"], "Le tympan transmet les vibrations aux osselets."),
    (4, "Quel est le plus petit os du corps humain ?", "L'étrier", ["Le marteau", "L'enclume", "Le coccyx", "La rotule"], "L'étrier se trouve dans l'oreille moyenne et mesure quelques millimètres."),
    (5, "Quel organe de l'oreille interne, en forme d'escargot, transforme les vibrations en signaux nerveux ?", "La cochlée", ["Le tympan", "L'étrier", "Le pavillon", "La trompe d'Eustache"], "Son nom vient du grec pour « escargot »."),
    (3, "Laquelle de ces saveurs fait partie des cinq saveurs de base ?", "L'umami", ["Le croquant", "Le fumé", "Le tiède", "Le parfumé"], "Les cinq saveurs sont sucré, salé, acide, amer et umami."),
    (2, "Quel organe permet de respirer en échangeant l'oxygène et le gaz carbonique ?", "Les poumons", ["Le foie", "Les reins", "L'estomac", "La rate"], "L'échange a lieu dans de minuscules sacs appelés alvéoles."),
    (4, "Comment s'appellent les minuscules sacs des poumons où l'oxygène passe dans le sang ?", "Les alvéoles", ["Les bronches", "Les ventricules", "Les villosités", "Les nodules"], "Les poumons contiennent des centaines de millions d'alvéoles."),
    (3, "Quel muscle, situé sous les poumons, joue un rôle clé dans la respiration ?", "Le diaphragme", ["Le biceps", "Le trapèze", "Le deltoïde", "Le quadriceps"], "En se contractant, il fait entrer l'air dans les poumons."),
    (2, "Quel organe du corps filtre le sang et fabrique l'urine ?", "Les reins", ["Le foie", "La vessie seule", "Le cœur", "L'estomac"], "Les deux reins épurent le sang des déchets."),
    (3, "Quel organe produit la bile, qui aide à digérer les graisses ?", "Le foie", ["Le pancréas", "L'estomac", "La rate", "Le cœur"], "Le foie est la plus grosse glande du corps."),
    (3, "Dans quelle partie du tube digestif la majorité des nutriments passent-ils dans le sang ?", "L'intestin grêle", ["L'estomac", "Le gros intestin", "L'œsophage", "La bouche"], "Ses parois sont couvertes de villosités qui augmentent la surface d'échange."),
    (4, "Quelle glande fabrique l'insuline, hormone qui régule le taux de sucre dans le sang ?", "Le pancréas", ["Le foie", "La thyroïde", "La rate", "Les glandes surrénales"], "Un manque d'insuline est à l'origine du diabète de type 1."),
    (2, "Comment s'appelle le tuyau qui conduit les aliments de la bouche à l'estomac ?", "L'œsophage", ["La trachée", "L'intestin", "Le pharynx seul", "L'urètre"], "La trachée, elle, conduit l'air vers les poumons."),
    (3, "Quels vaisseaux sanguins emportent le sang qui part du cœur vers le corps ?", "Les artères", ["Les veines", "Les capillaires seulement", "Les alvéoles", "Les nerfs"], "Les veines ramènent le sang vers le cœur."),
    (4, "Comment s'appelle la plus grosse artère du corps humain ?", "L'aorte", ["La carotide", "La veine cave", "L'artère pulmonaire", "La jugulaire"], "L'aorte part du ventricule gauche et distribue le sang oxygéné."),
    (5, "Quel médecin anglais a décrit en 1628 la circulation du sang dans un circuit fermé ?", "William Harvey", ["Edward Jenner", "Galien", "Andreas Vésale", "Joseph Lister"], "Il a compris que le cœur fait circuler le même sang en boucle."),
    (3, "Combien de chromosomes un être humain possède-t-il dans la plupart de ses cellules ?", "46", ["23 paires de 4", "32", "64", "100"], "Il y a 23 paires de chromosomes, soit 46."),
    (4, "Combien de côtes (au total) compte le thorax d'un humain adulte en général ?", "24", ["12", "18", "30", "36"], "Il y a douze paires de côtes."),
    (4, "Combien de vertèbres cervicales a une girafe, comme les humains ?", "Sept", ["Cinq", "Douze", "Vingt", "Trois"], "Presque tous les mammifères ont sept vertèbres du cou, la girafe comme l'humain."),
    (2, "Quelle est la température normale du corps humain ?", "Environ 37 °C", ["Environ 30 °C", "Environ 25 °C", "Environ 42 °C", "Environ 50 °C"], "Elle varie légèrement au cours de la journée."),
    (3, "Quel pigment donne sa couleur à la peau et la protège en partie du soleil ?", "La mélanine", ["La kératine", "L'hémoglobine", "La chlorophylle", "L'insuline"], "Plus on en a, plus la peau est foncée."),
    (4, "Quelle protéine compose l'essentiel des cheveux et des ongles ?", "La kératine", ["Le collagène", "L'hémoglobine", "La mélanine", "L'insuline"], "Elle forme aussi la couche externe de la peau."),
    (4, "Quel est le tissu le plus dur du corps humain ?", "L'émail des dents", ["Le fémur", "Le crâne", "Le cartilage", "L'ivoire"], "L'émail est plus dur que l'os."),
    (3, "Quel est le rôle des neurones ?", "Transmettre des messages nerveux", ["Digérer les aliments", "Fabriquer le sang", "Produire de l'énergie solaire", "Protéger les os"], "Ils communiquent entre eux par des signaux électriques et chimiques."),
    (3, "Où la moelle épinière est-elle située ?", "Dans la colonne vertébrale", ["Dans le crâne", "Dans la cage thoracique", "Dans les jambes", "Dans l'abdomen"], "Elle relie le cerveau au reste du corps."),
    (4, "Quelle vitamine, qui s'acquiert surtout grâce au soleil, aide à fixer le calcium sur les os ?", "La vitamine D", ["La vitamine C", "La vitamine A", "La vitamine K", "La vitamine B12"], "Un manque de vitamine D chez l'enfant peut provoquer le rachitisme."),
    (4, "Quel manque de vitamine provoquait le scorbut chez les marins d'autrefois ?", "La vitamine C", ["La vitamine D", "La vitamine A", "La vitamine B1", "La vitamine E"], "Les agrumes et les légumes frais le préviennent."),
    (3, "Quelle maladie un manque de fer dans l'alimentation peut-il provoquer ?", "Une anémie", ["Un rhume", "Une fracture", "Une allergie solaire", "Une otite"], "L'organisme manque alors d'hémoglobine."),
    (4, "Quel médecin britannique a mis au point en 1796 le premier vaccin, contre la variole ?", "Edward Jenner", ["Louis Pasteur", "Joseph Lister", "Alexander Fleming", "Robert Koch"], "Il observa que les trayeuses atteintes de la vaccine étaient protégées de la variole."),
    (4, "Louis Pasteur et son équipe ont testé avec succès en 1885 un vaccin contre quelle maladie ?", "La rage", ["Le choléra", "La tuberculose", "La rougeole", "Le paludisme"], "Le premier patient fut un jeune garçon, Joseph Meister."),
    (5, "En quelle année l'Organisation mondiale de la santé a-t-elle déclaré la variole éradiquée dans le monde ?", "1980", ["1960", "1975", "1992", "2000"], "C'est la seule maladie humaine déclarée éradiquée grâce à la vaccination de masse."),
    (5, "Quel médecin allemand a identifié en 1882 le bacille responsable de la tuberculose ?", "Robert Koch", ["Rudolf Virchow", "Paul Ehrlich", "Wilhelm Röntgen", "Emil von Behring"], "Il reçut le prix Nobel de médecine en 1905."),
    (4, "Quel physicien allemand a découvert les rayons X en 1895 ?", "Wilhelm Röntgen", ["Marie Curie", "Henri Becquerel", "Max Planck", "Heinrich Hertz"], "Il fit la première radiographie sur la main de son épouse."),
    (5, "Qui a mis au point le stéthoscope, vers 1816 ?", "René Laennec", ["Louis Pasteur", "Ambroise Paré", "Claude Bernard", "Paul Broca"], "Ce médecin français utilisa d'abord un simple tube de papier roulé."),
    (5, "Quels chercheurs ont isolé l'insuline en 1921 au Canada ?", "Frederick Banting et Charles Best", ["Alexander Fleming et Howard Florey", "Jonas Salk et Albert Sabin", "James Watson et Francis Crick", "Louis Pasteur et Émile Roux"], "Ils ont permis de traiter le diabète de type 1."),
    (5, "En quelle année la séquence complète du génome humain a-t-elle été déclarée achevée ?", "2003", ["1990", "1985", "1999", "2015"], "Le Projet génome humain a duré une douzaine d'années."),
    (4, "Quelle est la moisissure dont Fleming a tiré la pénicilline ?", "Un Penicillium", ["Un champignon de Paris", "Une levure de boulanger", "Une algue verte", "Un lichen"], "Il remarque en 1928 que la moisissure détruit des bactéries sur sa boîte de culture."),
    (5, "Quels trois chercheurs ont reçu le prix Nobel de médecine 1945 pour la pénicilline ?", "Fleming, Florey et Chain", ["Pasteur, Roux et Koch", "Salk, Sabin et Enders", "Banting, Best et Macleod", "Watson, Crick et Wilkins"], "Florey et Chain ont développé la pénicilline en médicament utilisable."),
    (4, "Quel moustique transmet le parasite responsable du paludisme ?", "L'anophèle femelle", ["Le moustique mâle", "L'aède du ciel", "La mouche tsé-tsé", "La puce de rat"], "Seule la femelle pique pour se nourrir de sang."),
    (5, "Quel médecin britannique a démontré en 1897 que le paludisme est transmis par les moustiques ?", "Ronald Ross", ["Alexandre Yersin", "Charles Laveran", "Edward Jenner", "Joseph Lister"], "Il reçut le prix Nobel de médecine en 1902."),
    (3, "Que signifie « ADN » dans la phrase « l'ADN contient les plans de l'être vivant » ?", "Acide désoxyribonucléique", ["Association de défense nutritionnelle", "Acide diazoté naturel", "Assemblage des noyaux", "Acide désinfectant naturel"], "La molécule d'ADN a la forme d'une double hélice."),
])

# ------------------------------------------------------------------------------------------------ animaux et plantes
rows("world-sci", "WORLD", "Animaux et plantes", [
    (2, "Comment s'appelle le petit de la grenouille, qui vit dans l'eau ?", "Le têtard", ["La larve de libellule", "Le chaton", "Le poussin", "L'alevin"], "Le têtard se transforme en grenouille par métamorphose."),
    (2, "Quelle est la forme d'un insecte juste avant de devenir papillon ?", "La chrysalide", ["L'œuf", "La larve de ver", "La nymphe aquatique", "La mue"], "La chenille s'enferme dans une chrysalide pour se transformer."),
    (2, "À quel groupe appartient l'araignée ?", "Les arachnides", ["Les insectes", "Les crustacés", "Les mollusques", "Les myriapodes"], "Elle a huit pattes, pas d'antennes, et son corps est en deux parties."),
    (3, "En combien de parties principales le corps d'un insecte est-il divisé ?", "Trois : tête, thorax, abdomen", ["Deux", "Quatre", "Cinq", "Sept"], "Les six pattes sont attachées au thorax."),
    (3, "Quel est le seul mammifère capable de voler vraiment ?", "La chauve-souris", ["L'écureuil volant", "Le phalanger volant", "Le colugo", "Le pangolin"], "Ses ailes sont formées d'une membrane tendue entre ses doigts."),
    (4, "Quel mammifère pond des œufs ?", "L'ornithorynque", ["Le tapir", "Le pangolin", "Le koala", "Le kangourou"], "L'ornithorynque et les échidnés sont des monotrèmes."),
    (2, "Quel animal porte son petit dans une poche ventrale ?", "Le kangourou", ["Le lion", "Le chimpanzé", "Le renard", "Le loup"], "Le kangourou est un marsupial d'Australie."),
    (3, "À quel groupe d'animaux appartient le requin ?", "Les poissons, à squelette de cartilage", ["Les mammifères marins", "Les reptiles marins", "Les mollusques", "Les crustacés"], "Les requins respirent par des branchies et ont un squelette de cartilage, pas d'os."),
    (2, "Comment appelle-t-on un animal qui ne mange que des plantes ?", "Un herbivore", ["Un carnivore", "Un omnivore", "Un insectivore", "Un décomposeur"], "La vache et la girafe sont des herbivores."),
    (1, "Quel est le plus grand oiseau du monde (qui ne vole pas) ?", "L'autruche", ["L'aigle", "Le pingouin", "Le flamant", "L'émeu"], "L'autruche d'Afrique peut courir à plus de 60 km/h."),
    (2, "Quel animal de la savane a un très long cou et mange les feuilles des acacias ?", "La girafe", ["Le zèbre", "Le buffle", "Le rhinocéros", "Le gnou"], "La girafe est l'animal terrestre le plus haut."),
    (3, "Dans une chaîne alimentaire, comment appelle-t-on les êtres vivants qui fabriquent leur matière grâce à la lumière ?", "Les producteurs", ["Les consommateurs", "Les prédateurs", "Les décomposeurs", "Les parasites"], "Les plantes vertes sont à la base des chaînes alimentaires."),
    (4, "Quel naturaliste suédois a créé au XVIIIe siècle la nomenclature binomiale (genre et espèce) ?", "Carl von Linné", ["Charles Darwin", "Georges Cuvier", "Buffon", "Alexander von Humboldt"], "Nous sommes ainsi Homo sapiens."),
    (5, "Dans la classification des êtres vivants, quel rang est directement plus large que l'espèce ?", "Le genre", ["La famille", "L'ordre", "Le règne", "La classe"], "L'ordre descendant : règne, embranchement, classe, ordre, famille, genre, espèce."),
    (3, "Il y a environ combien de temps les dinosaures non aviens ont-ils disparu ?", "Il y a environ 66 millions d'années", ["Il y a environ 6 000 ans", "Il y a environ 500 000 ans", "Il y a environ 2 milliards d'années", "Il y a environ 10 millions d'années"], "L'impact d'un astéroïde est la cause la plus acceptée."),
    (4, "Sur quelle île de l'océan Indien vivait le dodo, oiseau disparu au XVIIe siècle ?", "L'île Maurice", ["Madagascar", "La Réunion", "Zanzibar", "Sri Lanka"], "Il ne volait pas et fut exterminé en moins de deux siècles après l'arrivée des Européens."),
    (4, "Combien de cœurs possède un poulpe ?", "Trois", ["Un", "Deux", "Quatre", "Huit"], "Deux cœurs alimentent les branchies et un autre le reste du corps."),
    (5, "Que sont les coraux, du point de vue de la classification ?", "Des animaux, les polypes", ["Des plantes marines", "Des champignons", "Des minéraux", "Des algues"], "Les colonies de polypes bâtissent un squelette calcaire."),
    (2, "Quel rôle jouent les abeilles dans la reproduction des fleurs ?", "Elles transportent le pollen", ["Elles mangent les graines", "Elles arrosent les plantes", "Elles coupent les tiges", "Elles protègent des vers"], "Cette pollinisation permet aux fleurs de produire des fruits."),
    (3, "Dans la ruche, quel insecte pond les œufs ?", "La reine", ["L'ouvrière", "Le faux-bourdon", "Le frelon", "La guêpe"], "Une seule reine règne sur une colonie."),
    (1, "Quelle partie de la plante absorbe l'eau et les sels minéraux dans le sol ?", "Les racines", ["Les feuilles", "Les fleurs", "Les fruits", "Les graines"], "Les racines ancrent aussi la plante dans le sol."),
    (3, "Quels produits la photosynthèse fabrique-t-elle ?", "Des sucres et du dioxygène", ["De l'eau et du sel", "Du dioxyde de carbone et de l'azote", "Des protéines et du méthane", "De la chaleur uniquement"], "L'énergie de la lumière sert à fabriquer du glucose à partir de CO₂ et d'eau."),
    (5, "Comment s'appellent les minuscules pores des feuilles par lesquels la plante échange des gaz ?", "Les stomates", ["Les chloroplastes", "Les alvéoles", "Les nervures", "Les pétioles"], "Ils s'ouvrent et se ferment selon la lumière et l'humidité."),
    (3, "Que permettent de compter les cernes d'un tronc d'arbre coupé ?", "L'âge de l'arbre", ["La hauteur de l'arbre", "Le nombre de feuilles", "La quantité de pluie en un jour", "Le nombre d'oiseaux"], "Un cerne se forme en général chaque année."),
    (3, "Quelles plantes portent des aiguilles au lieu de feuilles plates ?", "Les conifères", ["Les palmiers", "Les fougères", "Les graminées", "Les mousses"], "Les pins et les sapins en sont des exemples."),
    (4, "Dans quel règne du vivant classe-t-on les champignons ?", "Un règne à part, ni plantes ni animaux", ["Parmi les plantes", "Parmi les animaux", "Parmi les minéraux", "Parmi les bactéries"], "Les champignons ne font pas de photosynthèse et se nourrissent de matière organique."),
    (4, "Quel moine a étudié l'hérédité en croisant des petits pois dans son jardin, au XIXe siècle ?", "Gregor Mendel", ["Carl Linné", "Charles Darwin", "Louis Pasteur", "Jean-Henri Fabre"], "Ses lois de l'hérédité ont été publiées en 1866 et redécouvertes vers 1900."),
    (3, "Quel navire a emmené Charles Darwin dans son tour du monde, en 1831-1836 ?", "Le Beagle", ["Le Mayflower", "Le Bounty", "L'Endeavour", "Le Calypso"], "Il y observa notamment les pinsons des îles Galápagos."),
    (3, "En quelle année Darwin a-t-il publié « L'Origine des espèces » ?", "1859", ["1809", "1831", "1889", "1905"], "Le livre expose la sélection naturelle."),
    (5, "Quelles plantes enrichissent le sol en azote grâce à des bactéries vivant dans leurs racines ?", "Les légumineuses", ["Les céréales", "Les conifères", "Les mousses", "Les cactus"], "Haricots, pois et trèfle en sont des exemples."),
])

# ------------------------------------------------------------------------------------------------ matière et chimie
rows("world-sci", "WORLD", "Matière et chimie", [
    (1, "Sous quels trois états la matière se présente-t-elle le plus couramment ?", "Solide, liquide et gazeux", ["Chaud, tiède et froid", "Lourd, léger et moyen", "Dur, mou et collant", "Clair, sombre et coloré"], "L'eau existe sous ces trois états : glace, eau liquide, vapeur."),
    (2, "Comment s'appelle le passage de l'état solide à l'état liquide ?", "La fusion", ["La solidification", "La condensation", "La vaporisation", "La sublimation"], "La glace fond à 0 °C."),
    (3, "Comment s'appelle le passage de l'état gazeux à l'état liquide ?", "La condensation", ["La fusion", "La vaporisation", "La solidification", "La sublimation"], "La buée sur une vitre froide en est un exemple."),
    (4, "Comment s'appelle le passage direct de l'état solide à l'état gazeux ?", "La sublimation", ["La fusion", "La condensation", "La vaporisation", "La liquéfaction"], "La glace sèche (CO₂ solide) se sublime à l'air libre."),
    (3, "Pourquoi un glaçon flotte-t-il sur l'eau ?", "La glace est moins dense que l'eau liquide", ["La glace est plus lourde", "L'eau est salée", "La glace est creuse", "L'eau chaude la soulève"], "L'eau gèle en occupant plus de volume."),
    (3, "De quoi le noyau d'un atome est-il constitué ?", "De protons et de neutrons", ["D'électrons seulement", "De molécules d'eau", "De photons", "D'atomes plus petits identiques"], "Les électrons tournent autour du noyau."),
    (3, "Quelle charge électrique porte un électron ?", "Négative", ["Positive", "Nulle", "Alternativement positive et négative", "Aucune charge"], "Le proton est positif, le neutron est neutre."),
    (4, "Quel chimiste russe a publié en 1869 la première version du tableau périodique des éléments ?", "Dmitri Mendeleïev", ["Antoine Lavoisier", "John Dalton", "Niels Bohr", "Ernest Rutherford"], "Il avait laissé des cases vides pour des éléments encore inconnus."),
    (5, "Que représente le numéro atomique d'un élément ?", "Le nombre de protons de son noyau", ["Le nombre de neutrons", "Sa masse en grammes", "Sa température de fusion", "Son année de découverte"], "L'hydrogène a le numéro 1, l'hélium le numéro 2."),
    (3, "Quel est le seul métal liquide à température ambiante ?", "Le mercure", ["Le plomb", "L'étain", "Le sodium", "Le zinc"], "Son symbole est Hg, du latin hydrargyrum."),
    (4, "De quels métaux le bronze est-il un alliage ?", "Cuivre et étain", ["Cuivre et zinc", "Fer et carbone", "Or et argent", "Plomb et étain"], "Le laiton, lui, associe cuivre et zinc."),
    (5, "De quels métaux le laiton est-il un alliage ?", "Cuivre et zinc", ["Cuivre et étain", "Fer et nickel", "Aluminium et cuivre", "Argent et plomb"], "Le laiton sert aux instruments de musique, comme les cuivres."),
    (4, "Quel élément s'allie au fer pour donner l'acier ?", "Le carbone", ["Le zinc", "Le cuivre", "L'étain", "Le plomb"], "Une petite quantité de carbone rend le fer beaucoup plus résistant."),
    (3, "Comment appelle-t-on la transformation du fer qui se couvre de rouille ?", "Une oxydation", ["Une fusion", "Une sublimation", "Une congélation", "Une photosynthèse"], "Le fer réagit avec l'oxygène en présence d'humidité."),
    (2, "De quoi une flamme a-t-elle besoin pour brûler ?", "D'oxygène", ["D'azote pur", "D'eau", "D'argon", "De sel"], "Sans air, une bougie s'éteint."),
    (4, "Quelle est la formule chimique du dioxyde de carbone ?", "CO₂", ["CO", "C₂O", "CH₄", "O₂"], "Une molécule contient un atome de carbone et deux d'oxygène."),
    (4, "Quelle est la formule chimique du méthane ?", "CH₄", ["CO₂", "C₂H₆", "NH₃", "H₂S"], "Le méthane est le principal constituant du gaz naturel."),
    (4, "Quelle molécule formée de trois atomes d'oxygène protège la Terre des ultraviolets en altitude ?", "L'ozone", ["Le dioxygène", "Le peroxyde", "L'azote", "Le monoxyde de carbone"], "Sa formule est O₃."),
    (3, "À quelle valeur du pH une solution est-elle neutre ?", "7", ["0", "1", "10", "14"], "L'eau pure est neutre : en dessous de 7 c'est acide, au-dessus basique."),
    (3, "Quel est le gaz le plus léger ?", "L'hydrogène", ["L'hélium", "L'oxygène", "L'azote", "Le méthane"], "L'hélium vient en deuxième position, mais l'hydrogène est plus léger."),
    (3, "Quel gaz rare est utilisé pour gonfler les ballons de fête qui s'envolent ?", "L'hélium", ["Le néon", "L'argon", "L'azote", "Le krypton"], "Il est plus léger que l'air et ne brûle pas."),
    (4, "À quel chimiste attribue-t-on la formule « Rien ne se perd, rien ne se crée, tout se transforme » ?", "Antoine Lavoisier", ["Louis Pasteur", "Isaac Newton", "Marie Curie", "Robert Boyle"], "C'est la formulation populaire de la conservation de la masse lors des réactions chimiques."),
    (4, "Quel gaz Lavoisier a-t-il identifié comme celui qui entretient la combustion ?", "L'oxygène", ["L'azote", "L'hydrogène", "Le dioxyde de carbone", "L'hélium"], "Il a aussi donné son nom à l'oxygène, au XVIIIe siècle."),
    (5, "Quel physicien a montré en 1911 que l'atome possède un noyau très petit et dense ?", "Ernest Rutherford", ["Niels Bohr", "J. J. Thomson", "John Dalton", "Max Planck"], "Il bombardait une fine feuille d'or avec des particules."),
    (5, "Quel physicien a découvert la radioactivité en 1896 ?", "Henri Becquerel", ["Marie Curie", "Wilhelm Röntgen", "Ernest Rutherford", "Pierre Curie"], "Il observa que des sels d'uranium impressionnaient des plaques photographiques."),
    (4, "Quels deux éléments ont été découverts en 1898 par Pierre et Marie Curie ?", "Le polonium et le radium", ["L'uranium et le thorium", "Le fluor et le chlore", "L'hélium et le néon", "Le plutonium et le césium"], "Marie Curie a nommé le polonium en l'honneur de la Pologne, son pays natal."),
])

